function toLowerCase(s) {
  const result = [];
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    if (code >= 65 && code <= 90) {
      result.push(String.fromCharCode(code + 32));
    } else {
      result.push(s[i]);
    }
  }
  return result.join('');
}

