function toLowerCase(s) {
  const upper = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const lower = 'abcdefghijklmnopqrstuvwxyz';
  let out = '';
  for (const ch of s) {
    const at = upper.indexOf(ch);
    out += at === -1 ? ch : lower[at];
  }
  return out;
}

