function generate(rand, size) {
  const length = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  // Small inputs lean on the characters right next to the capital range ('@', '[', '`', '{') to expose off-by-one bounds.
  const tricky = '@AZ[`az{ 09~';
  let s = '';
  for (let i = 0; i < length; i++) {
    if (size === 'small' && rand() < 0.5) s += tricky[Math.floor(rand() * tricky.length)];
    else s += String.fromCharCode(32 + Math.floor(rand() * 95));
  }
  return [s];
}
